$values.ConditionExpression:
@prefix cmw: <http://comindware.com/logics#>.
@prefix account: <http://comindware.com/ontology/account#>.
{

    cmw:securityContext cmw:currentUser ?user.

    if {?user account:userGroupMembership ?group.
       or
           {?group account:groupName "Начальник управления beg_sof".}
           or
           {?group account:groupName "Начальник центрального аппарата".}.}
    then {true -> ?value.}

}
